      SUBROUTINE RBGETCC     PARAMETERS FOR THE CENTRAL FIELD OF RBEND AND SBENDC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4B.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM28.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC-----------------------------------------------------------------------------CC     INDICES FOR PARAMETERSC      NL = 1      NBV = 2      NRHO = 3      NANG = 4      NN = 5      NK1 = 6      NRMPS = 7C      IL = IPTOJ(NL)      IB = IPTOJ(NBV)      IRHO = IPTOJ(NRHO)      IANG = IPTOJ(NANG)CC     MAGNET LENGTHC      IF (IL .EQ. 0) GO TO 25      IADR = I + IL      LBEND = DATAR(IADR)      IF (PRAN28(NL) .NE. 0.0) LBEND = LBEND + PRAN28(NL)*XRAN(NL)      LBEND = LBEND*UNITI(8)      IF (TYPE .EQ. 28) LRBEND = LBENDCC     MAGNET LENGTH AND FIELDC      IF (IB .EQ. 0) GO TO 15      IADR = I + IB      B = DATAR(IADR)      IF (PRAN28(NBV) .NE. 0.0) B = B + PRAN28(NBV)*XRAN(NBV)      B = B*UNITI(9)*RI/PREF      H0 = B/RI      RHO = 0.0      IF (H0 .NE. 0.0) RHO = 1.0/H0      IF (TYPE .EQ. 28 .AND. H0 .NE. 0.0) THEN        AL = 2.0*ASIN(LBEND/(2.0*RHO))        LBEND = RHO*AL      ELSE        AL = H0*LBEND      ENDIF      GO TO 35CC     MAGNET LENGTH AND RADIUS OF CURVATUREC   15 IF (IRHO .EQ. 0) GO TO 20      IADR = I + IRHO      RHO = DATAR(I+IRHO)      IF (PRAN28(NRHO) .NE. 0.0) RHO = RHO + PRAN28(NRHO)*XRAN(NRHO)      RHO = RHO*UNITI(8)      H0 = 1.0/RHO      IF (RI .NE. 0.0) B = H0*RI      IF (TYPE .EQ. 28) THEN        AL = 2.0*ASIN(LBEND/(2.0*RHO))        LBEND = RHO*AL      ELSE        AL = H0*LBEND      ENDIF      GO TO 35CC     MAGNET LENGTH AND ANGLEC   20 IADR = I + IANG      AL = DATAR(IADR)      IF (PRAN28(NANG) .NE. 0.0) AL = AL + PRAN28(NANG)*XRAN(NANG)      AL = AL*UNITI(7)      IF (TYPE .EQ. 28) THEN        H0 = 2.0*SIN(0.5*AL)/LBEND        IF (H0 .NE. 0) THEN          LBEND = AL/H0        ENDIF      ELSE        H0 = AL/LBEND      ENDIF      B = RI*H0      GO TO 35CC     MAGNETIC FIELD AND BEND ANGLEC   25 IF (IB .EQ. 0) GO TO 30      IADR = I + IB      B = DATAR(IADR)      IF (PRAN28(NBV) .NE. 0.0) B = B + PRAN28(NBV)*XRAN(NBV)      B = B*UNITI(9)*RI/PREF      IADR = I + IANG      AL = DATAR(IADR)      IF (PRAN28(NANG) .NE. 0.0) AL = AL + PRAN28(NANG)*XRAN(NANG)      AL = AL*UNITI(7)      H0 = B/RI      IF (H0 .NE. 0.0) RHO = 1.0/H0      LBEND = RHO*AL      LRBEND = 2.0*RHO*SIN(0.5*AL)      GO TO 35CC     RADIUS OF CURVATURE AND BEND ANGLEC   30 IADR = I + IRHO      RHO = DATAR(IADR)      IF (PRAN28(NRHO) .NE. 0.0) RHO = RHO + PRAN28(NRHO)*XRAN(NRHO)      RHO = RHO*UNITI(8)      IADR = I + IANG      AL = DATAR(IADR)      IF (PRAN28(NANG) .NE. 0.0) AL = AL + PRAN28(NANG)*XRAN(NANG)      AL = AL*UNITI(7)      LBEND = RHO*AL      IF (RI .NE. 0.0) B = RI/RHO      H0 = 1.0/RHO      LRBEND = 2.0*RHO*SIN(0.5*AL)CC     FRACTIONAL FIELD EXCESSC   35 IRMPS = IPTOJ(NRMPS)      IF (IRMPS .NE. 0) THEN        IADR = I + IRMPS        RMPS = DATAR(IADR)      ELSE        RMPS = RMPSI      ENDIF      IF (PRAN28(NRMPS) .NE. 0.0)     1    RMPS = RMPS + PRAN28(NRMPS)*XRAN(NRMPS)      RH = 1.0 + RMPS      H = RH*H0CC     NORMALIZED FIELD GRADIENTC      NB = 0.0      IN = IPTOJ(NN)      IK1 = IPTOJ(NK1)      IF (IK1 .EQ. 0 .AND. PRAN28(NK1) .EQ. 0.0) THEN        IF (IN .EQ. 0) THEN          NB = 0.0        ELSE          IADR = I + IN          NB = DATAR(IADR)        ENDIF        IF (PRAN28(NN) .NE. 0.0) NB = NB + PRAN28(NN)*XRAN(NN)      ELSE         IF (IK1 .EQ. 0) THEN          K1 = 0.0        ELSE          IADR = I + IK1          K1 = DATAR(IADR)        ENDIF        IF (PRAN28(NK1) .NE. 0.0) K1 = K1 + PRAN28(NK1)*XRAN(NK1)        K1 = K1/UNITI(8)**2        IF (H0 .NE. 0.0) NB = - K1/H0**2      ENDIFCC     VARY CODE FOR CENTRAL FIELDC      IBVARY = I + IB   50 NBVARY = TIE(IBVARY)      IF (NBVARY .EQ. 100) THEN        IBVARY = IDATA(IBVARY)        GO TO 50      ENDIFC      IT = IPTOJ(25)      IF (IT .EQ. 0) THEN        NUMTYP = IT      ELSE        NUMTYP = IDATA(I + IT)      ENDIF      RETURN      END